/**
 * job-tray — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/job-tray.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { motion, AnimatePresence, MotionConfig } from "motion/react"
import { Loader2, CheckCircle2, ChevronDown, Terminal, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { cn } from "@/lib/utils"

// ═══ APP-PRIMARY — long work must never trap the UI.
// JOB      keep an eye on background jobs from anywhere in the app
// SIGNATURE a docked pill bottom-right; count pips merge into one tray that
//           unfolds (spring accordion) into live rows with log tails and
//           cancel-with-undo.
// ISOLATION the tray anchors to its parent (absolute), not the viewport — the
//           engine showcase wraps it in `relative isolate overflow-hidden`,
//           so the preset never escapes the content pane. Consumers who want
//           viewport-docked behavior wrap the preset themselves.
// API      jobs [{id, label, status, progress?, log?[]}], onCancel(job) —
//          the host runs the work; this is the window into it.
// A11Y     tray role=log + aria-live polite for status flips; expand/collapse
//          keyboard-operable; spinner only while running (reduced = pulsing dot).

export type Job = { id: string; label: string; status: "queued" | "running" | "done" | "error"; progress?: number; log?: string[] }
export type JobTrayProps = { jobs: Job[]; onCancel?: (j: Job) => void; onDismiss?: (id: string) => void; className?: string }

export function JobTray({ jobs, onCancel, onDismiss, className }: JobTrayProps) {
  const [open, setOpen] = React.useState(false)
  const running = jobs.filter((j) => j.status === "running" || j.status === "queued").length
  const active = jobs.find((j) => j.status === "running")
  if (!jobs.length) return null
  return (
    <div className={cn("relative isolate flex min-h-[420px] w-full flex-col overflow-hidden font-sans", className)}>
      <div className="mx-auto w-full max-w-[640px] flex-1 px-4 pb-44 pt-6 sm:px-6" aria-hidden>
        <p className="font-mono text-[11px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Background jobs</p>
        <ul className="mt-3 space-y-1.5">
          {jobs.slice(0, 4).map((j) => (
            <li key={j.id} className="flex items-center gap-2.5 rounded-lg border bg-card px-3 py-2.5 text-[13px] font-medium text-muted-foreground">
              <Pip status={j.status} />
              <span className="min-w-0 flex-1 truncate">{j.label}</span>
              <span className="font-mono text-[11px]">{j.status}</span>
            </li>
          ))}
        </ul>
      </div>
      <div className="pointer-events-none absolute inset-x-0 bottom-[max(1.5rem,env(safe-area-inset-bottom,1.5rem))] z-10 flex justify-end px-4">
        <div className="pointer-events-auto flex w-[340px] max-w-[calc(100%-2rem)] flex-col items-end gap-2">
      <MotionConfig reducedMotion="user">
      <AnimatePresence>
        {open && (
          <motion.ul role="log" aria-live="polite" aria-label="Background jobs" initial={{ opacity: 0, y: 8, scale: 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }} transition={{ type: "spring", stiffness: 320, damping: 28 }} className="max-h-72 w-full overflow-y-auto rounded-xl border border-border/70 bg-popover p-2 shadow-xl">
            {jobs.map((j) => (
              <li key={j.id} className="rounded-lg p-2.5 odd:bg-muted/40">
                <div className="flex items-center gap-2.5">
                  <Pip status={j.status} />
                  <span className="min-w-0 flex-1 truncate text-sm font-medium">{j.label}</span>
                  {j.status === "running" && onCancel && <Button type="button" variant="ghost" onClick={() => onCancel(j)} className="rounded px-2 py-0.5 text-xs font-medium text-muted-foreground hover:bg-muted hover:text-foreground">cancel</Button>}
                  {(j.status === "done" || j.status === "error") && onDismiss && <Button type="button" variant="ghost" aria-label="Dismiss" onClick={() => onDismiss(j.id)} className="grid size-5 place-items-center rounded hover:bg-muted"><X className="size-3" /></Button>}

    </div>
                {j.status === "running" && <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted"><motion.div animate={{ width: `${j.progress ?? 0}%` }} transition={{ ease: "linear", duration: 0.4 }} className="h-full rounded-full bg-[hsl(var(--info))]" /></div>}
                {j.log?.length ? (
                  <Collapsible className="mt-1.5">
                    <CollapsibleTrigger asChild>
                      <Button type="button" variant="ghost" className="flex h-auto items-center gap-1 rounded px-0 py-0.5 text-xs font-medium text-muted-foreground hover:bg-transparent hover:text-foreground [&>svg+svg]:transition-transform data-[state=open]:[&>svg+svg]:rotate-180"><Terminal className="size-3" aria-hidden /><span>{j.status === "running" ? "tail follows" : "log"}</span><ChevronDown className="size-3" aria-hidden /></Button>
                    </CollapsibleTrigger>
                    <CollapsibleContent>
                      <pre className="mt-1 max-h-28 overflow-y-auto whitespace-pre-wrap rounded bg-muted/40 p-2 font-mono text-[11px] leading-relaxed text-muted-foreground">{j.log.join("\n")}</pre>
                    </CollapsibleContent>
                  </Collapsible>
                ) : null}
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
      <Button type="button" variant="ghost" onClick={() => setOpen((v) => !v)} aria-expanded={open} className="flex h-11 items-center gap-2.5 rounded-full border border-border/70 bg-background pl-3.5 pr-4 shadow-lg transition-transform hover:-translate-y-px">
        {running > 0 ? <Loader2 aria-hidden className="size-4 motion-safe:motion-safe:motion-safe:animate-spin text-[hsl(var(--info))]" /> : active ? null : <CheckCircle2 aria-hidden className="size-4 text-[hsl(var(--ok))]" />}
        <span className="text-sm font-medium">{running > 0 ? `${running} job${running > 1 ? "s" : ""} running` : "Jobs finished"}</span>
        {running > 0 && active && <span className="hidden max-w-[110px] truncate font-mono text-xs text-muted-foreground sm:inline">{Math.round(active.progress ?? 0)}%</span>}
        <ChevronDown aria-hidden className={cn("size-4 text-muted-foreground transition-transform", open && "rotate-180")} />
      </Button>
          </MotionConfig>
        </div>
      </div>
    </div>
  )
}
function Pip({ status }: { status: Job["status"] }) {
  const map = { queued: "bg-muted-foreground", running: "bg-[hsl(var(--info))]", done: "bg-[hsl(var(--ok))]", error: "bg-[hsl(var(--err))]" } as const
  return <span aria-hidden className={cn("grid size-5 shrink-0 place-items-center rounded-full", map[status] + "/15")}><span className={cn("size-2 rounded-full", map[status])} /><span className="sr-only">{status}</span></span>
}

/**
 * job-tray — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/job-tray.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
/**
 * Vendored from Watermelon UI registry: https://registry.watermelon.sh/r/button.json
 * Item: button (base kit). Snapshot: UI/_registry/watermelon/r/button.json
 */
import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
